// Intended function: generate reproducible ecological variety without storing whole species catalogs until a species becomes discovered/persistent.
#include "world/ProceduralSpecies.hpp"
#include "core/Determinism.hpp"
#include <algorithm>
namespace elysium{namespace{float u(std::uint64_t s,int n){auto h=mix64(s^std::uint64_t(n)*0x9e3779b97f4a7c15ULL);return float((h>>40)&0xffffff)/float(0xffffff);}}ProceduralSpecies generateSpecies(std::uint64_t p,std::uint32_t n,float g,float t,float ocean){auto s=mix64(p^mix64(n)^0x4641554E41ULL);ProceduralSpecies x;x.speciesId=mix64(s^0x53504543494553ULL);x.bodyPlan=FaunaBodyPlan(std::uint8_t(u(s,1)*6)%6);if(ocean>.55f&&u(s,2)<ocean)x.bodyPlan=FaunaBodyPlan::Aquatic;x.diet=FaunaDiet(std::uint8_t(u(s,3)*6)%6);x.size=.15f+u(s,4)*5.f/(.5f+std::max(.2f,g));x.mass=x.size*x.size*x.size*(20+u(s,5)*80);x.speed=1+u(s,6)*14;x.armor=u(s,7);x.aggression=u(s,8);x.curiosity=u(s,9);x.sociality=u(s,10);x.heatTolerance=std::clamp(.5f+t*.02f+(u(s,11)-.5f)*.4f,0.f,1.f);x.coldTolerance=1-x.heatTolerance*.7f;x.limbPairs=std::uint8_t(1+u(s,12)*4);x.colorHue=std::uint8_t(u(s,13)*255);x.pattern=std::uint8_t(u(s,14)*8);x.flying=x.bodyPlan==FaunaBodyPlan::Avian||u(s,15)<.08f;x.burrowing=u(s,16)<.18f;x.amphibious=x.bodyPlan!=FaunaBodyPlan::Aquatic&&u(s,17)<ocean*.35f;x.venomous=u(s,18)<.12f;x.bioluminescent=u(s,19)<.15f;return x;}std::vector<ProceduralSpecies>generateSpeciesSet(std::uint64_t p,std::uint32_t c,float g,float t,float o){std::vector<ProceduralSpecies>v;v.reserve(c);for(std::uint32_t i=0;i<c;++i)v.push_back(generateSpecies(p,i,g,t,o));return v;}}
